    def maxHeight(self, cuboids: List[List[int]]) -> int:
        dp=[0]*len(cuboids)
        max_value=0
        for i in range(len(cuboids)):
            cuboids[i].sort()
        cuboids.sort()
        for i in range(len(cuboids)):
            dp[i]=cuboids[i][2]
            for j in range(i):
                if cuboids[i][0]>=cuboids[j][0] and cuboids[i][1]>=cuboids[j][1] and cuboids[i][2]>=cuboids[j][2]:
                    dp[i]=max(dp[i],dp[j]+cuboids[i][2])
            if dp[i]>max_value:
                max_value=dp[i]
        return max_value

class Solution:
    def checkPartitioning(self, s: str) -> bool:
        n = len(s)

        @lru_cache(None)
        def pal(i,j):
            if i == j:
                return True
            if s[i] != s[j]:
                return False
            if i+1 == j:
                return True
            else:
                return pal(i+1,j-1)

        for i in range(n-2):
            if pal(0,i):
                for j in range(i+1,n-1):
                    if pal(i+1,j) and pal(j+1,n-1):
                        return True
        return False

