class Solution:
    def maximumScore(self, nums: List[int], multipliers: List[int]) -> int:
        n = len(nums)
        m = len(multipliers)

        @lru_cache(None)
        #To Save Computed Result

        def X(i, left):

            if i==m:
                return 0

            return max  (   (multipliers[i] * nums[left])          + X(i + 1, left + 1), 
                            (multipliers[i] * nums[n-1-(i-left)])  + X(i + 1, left)       )        

        #Start from Zero operations
        return X(0,0)

class Solution:
	def longestPalindrome(self, word1: str, word2: str) -> int:
		res=0
		new_word=word1+word2
		n,mid=len(word1)+len(word2),len(word1)
		dp=[[0]*n for _ in range(n)]
		for i in range(n):
			dp[i][i]=1
		for l in range(n-2,-1,-1):
			for r in range(l+1,n,1):
				if new_word[l]==new_word[r]:
					dp[l][r]=(dp[l+1][r-1] if r-1>=l+1 else 0)+2
					if l<mid and r>=mid:
						res=max(res,dp[l][r])
				else:
					dp[l][r]=max(dp[l+1][r],dp[l][r-1])
		return res

import collections

class Solution:
    def minChanges(self, nums, k):
        def one_are_not_from_nums(nums, cnts):
            mxs = [cnts[i].most_common(1)[0][1] for i in range(k)]
            return len(nums) - (sum(mxs)-min(mxs))

        def all_are_from_nums(nums, cnts):
            dp = {0:0}
            for cnt in cnts:
                new_dp = collections.defaultdict(int)
                for x in dp.keys():
                    for y in cnt.keys():
                        new_dp[x^y] = max(new_dp[x^y], dp[x]+cnt[y])
                dp = new_dp
            return len(nums)-dp[0]

        cnts = [collections.Counter(nums[j] for j in range(i, len(nums), k)) for i in range(k)]
        return min(one_are_not_from_nums(nums, cnts), all_are_from_nums(nums, cnts))

