class Solution:
    def minSkips(self, dist: List[int], speed: int, hoursBefore: int) -> int:
        if sum(dist)/speed > hoursBefore: return -1 # impossible 

        @cache
        def fn(i, k): 
            """Return min time (in distance) of traveling first i roads with k skips."""
            if k < 0: return inf # impossible 
            if i == 0: return 0 
            return min(ceil((fn(i-1, k) + dist[i-1])/speed) * speed, dist[i-1] + fn(i-1, k-1))

        for k in range(len(dist)):
            if fn(len(dist)-1, k) + dist[-1] <= hoursBefore*speed: return k

class Solution:
    def minOperationsToFlip(self, expression: str) -> int:
        loc = {}
        stack = []
        for i in reversed(range(len(expression))):
            if expression[i] == ")": stack.append(i)
            elif expression[i] == "(": loc[stack.pop()] = i 

        def fn(lo, hi): 
            """Return value and min op to change value."""
            if lo == hi: return int(expression[lo]), 1
            if expression[hi] == ")" and loc[hi] == lo: return fn(lo+1, hi-1) # strip parenthesis 
            mid = loc.get(hi, hi) - 1 
            v, c = fn(mid+1, hi)
            vv, cc = fn(lo, mid-1)
            if expression[mid] == "|": 
                val = v | vv 
                if v == vv == 0: chg = min(c, cc)
                elif v == vv == 1: chg = 1 + min(c, cc)
                else: chg = 1 
            else: # expression[k] == "&"
                val = v & vv
                if v == vv == 0: chg = 1 + min(c, cc)
                elif v == vv == 1: chg = min(c, cc)
                else: chg = 1
            return val, chg

        return fn(0, len(expression)-1)[1]

class Solution:
    def colorTheGrid(self, m: int, n: int) -> int:
        from functools import reduce
        MOD = 10**9 + 7
        sum_mod = lambda x,y: (x+y)%MOD

        def normalize(pat_var):
            mapping = { e:i+1 for i, e in enumerate(pat_var[0:2]) }
            mapping[list({1,2,3}.difference(mapping.keys()))[0]] = 3
            return tuple([ mapping[e] for e in pat_var])

        def get_pats(m, i, pat, pats):
            if i == m-1:
                pats.append(tuple(pat))
                return
            i_nx = i+1
            for p_it_nx in (1,2,3):
                if (i_nx <= 1 and p_it_nx == i_nx+1 ) or (i_nx >= 2 and p_it_nx != pat[-1]):
                    pat.append(p_it_nx)
                    get_pats(m, i_nx, pat, pats)
                    pat.pop()
            return pats

        def get_trans(pat, i, pat_pre, trans):
            if i == len(pat)-1:
                pat_nl = normalize(pat_pre)
                trans[pat_nl] = trans.get(pat_nl, 0) + 1
                return
            for p_it_pre in (1,2,3):
                i_nx = i+1
                if (p_it_pre != pat[i_nx]
                    and (not pat_pre or p_it_pre != pat_pre[-1])):
                    pat_pre.append(p_it_pre)
                    get_trans(pat, i_nx, pat_pre, trans)
                    pat_pre.pop()
            return trans

        pats = get_pats(m, -1, [], [])
        # {pattern_i: {pattern_pre:count}}
        pat_trans = { pat: get_trans(pat, -1, [], {}) for pat in pats }  

        p_counts = { pat:1 for pat in pat_trans.keys() }
        for i in range(n-1):
            p_counts_new = {}
            for pat, trans in pat_trans.items():
                p_counts_new[pat] = reduce(sum_mod, (p_counts[pat_pre] * cnt for pat_pre, cnt in trans.items()))
            p_counts = p_counts_new

        res = reduce(sum_mod, (cnt for cnt in p_counts.values()))
        perms = reduce(lambda x,y: x*y, (3-i for i in range(min(3,m))))
        return (res * perms) % MOD

